const q = $input.first().json.query || {};
const sellerId = q.seller_id;

if (!sellerId) {
  throw new Error('Parâmetro seller_id é obrigatório');
}

return [{ json: { sellerId: String(sellerId) } }];

const rows = $input.all();
if (!rows || rows.length === 0) {
  return [{ json: { products: [], total: 0 } }];
}

const products = rows.map(function(row) {
  const p = row.json;
  const amount = parseFloat(p.amount) || 0;
  return {
    id:          String(p.id),
    name:        p.name,
    status:      p.status,
    price:       amount > 0 ? 'R$ ' + amount.toLocaleString('pt-BR', { minimumFractionDigits: 0 }) : null,
    priceRaw:    amount,
    thumbnail:   p.thumbnail || null,
    format:      p.format || null,
    warranty:    p.warranty || null,
    maxInstallments: p.max_installments || null
  };
});

return [{ json: { products: products, total: products.length } }];
